[Form]
public class METRetroDiscountSalesInvoiceGenerateDialog extends FormRun
{
    private QueryBuildRange offerIdRange;
    private Query productPreviewQuery;
    private Query custPreviewQuery;
    private Query productVariantPreviewQuery;
    private GUPPricingRuleCopy pricingRuleCopyLine;
    private GUPPricingRuleCopy pricingRuleCopyHeader;

}

public void init()
{
    super();

    element.initDateTypeControl();
    element.initPricingObjectPreviewQuery();
}

private void initPricingObjectPreviewQuery()
{
    Query inventTableQuery, custTableQuery, productVariantQuery;

    custTableQuery = new Query();
    custTableQuery.addDataSource(tableNum(CustTable))
        .addRange(fieldNum(CustTable, RecId))
        .value(int2Str(-1));

    inventTableQuery = new Query();
    inventTableQuery.addDataSource(tableNum(InventTable))
        .addRange(fieldNum(InventTable, RecId))
        .value(int2Str(-1));

    productVariantQuery = new Query();
    productVariantQuery.addDataSource(tableNum(EcoResDistinctProductVariant))
        .addRange(fieldNum(EcoResDistinctProductVariant, RecId))
        .value(int2Str(-1));

    this.custPreviewQuery = custTableQuery;
    this.productPreviewQuery = inventTableQuery;
    this.productVariantPreviewQuery = productVariantQuery;
}

private void initCustTablePreview()
{
    if (pricingRuleCopyHeader.PriceAttributeGroupName != '')
    {
        element.custPreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingRuleCopy(pricingRuleCopyHeader).build();
        CustTable_ds.executeQuery();
    }
    else
    {
        PreviewCustTabPage.visible(false);
    }
}

private void initInventTablePreview()
{
    if (pricingRuleCopyLine.PriceAttributeGroupName != '')
    {
        if (pricingRuleCopyLine.ExclusionType == GUPPricingRuleExclusionType::ProductVariant)
        {
            element.productVariantPreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingRuleCopy(pricingRuleCopyLine).addProductVariants().build();
            EcoResDistinctProductVariant_ds.executeQuery();
            PreviewProductVariantTabPage.visible(true);
            PreviewProductTabPage.visible(false);
        }
        else
        {
            element.productPreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingRuleCopy(pricingRuleCopyLine).build();
            InventTable_ds.executeQuery();
            PreviewProductVariantTabPage.visible(false);
            PreviewProductTabPage.visible(true);
        }
    }
    else
    {
        PreviewProductVariantTabPage.visible(false);
        PreviewProductTabPage.visible(false);
    }
}

public void closeOk()
{
    RetailOfferIdEx3 discountId = OfferId.valueStr();

    if (discountId)
    {
        super();

        METRetroDiscountSalesInvoiceGenerate transGenerate =
            new METRetroDiscountSalesInvoiceGenerate(
                discountId,
                FromDate.dateValue(),
                ToDate.dateValue(),
                DateType.selection());

        transGenerate.run();
    }
}

public display str displayCustTableExclusion(CustTable _custTable)
{
    GUPPricingRuleExclusionCopy excluded;
    select firstonly RecId from excluded where excluded.Exclusion == _custTable.AccountNum && excluded.RuleId == pricingRuleCopyHeader.RuleId;

    if (excluded.RecId)
    {
        return "@GlobalUnifiedPricing:GUPAddPriceAttributeGroup_Exclude";
    }
    else
    {
        return "@GlobalUnifiedPricing:GUPAddPriceAttributeGroup_Include";
    }
}

public display str displayInventTableExclusion(InventTable _inventTable)
{
    GUPPricingRuleExclusionCopy excluded;
    select firstonly RecId from excluded where excluded.Exclusion == _inventTable.ItemId && excluded.RuleId == pricingRuleCopyLine.RuleId;

    if (excluded.RecId)
    {
        return "@GlobalUnifiedPricing:GUPAddPriceAttributeGroup_Exclude";
    }
    else
    {
        return "@GlobalUnifiedPricing:GUPAddPriceAttributeGroup_Include";
    }
}

public display str displayProductVariantExclusion(EcoResDistinctProductVariant _productVariant)
{
    GUPPricingRuleExclusionCopy excluded;
    select firstonly RecId from excluded where excluded.Exclusion == int642Str(_productVariant.RecId) && excluded.RuleId == pricingRuleCopyLine.RuleId;

    if (excluded.RecId)
    {
        return "@GlobalUnifiedPricing:GUPAddPriceAttributeGroup_Exclude";
    }
    else
    {
        return "@GlobalUnifiedPricing:GUPAddPriceAttributeGroup_Include";
    }
}

public void init()
{
    super();

    QueryBuildDataSource qbds = this.query().dataSourceTable(tableNum(RetailPeriodicDiscountLine));
    offerIdRange = qbds.addRange(fieldNum(RetailPeriodicDiscountLine, OfferId));
}

public int active()
{
    int ret = super();

    RetailPeriodicDiscountLine  discountLine;
    GUPPricingRuleCopy          ruleCopyLine;

    discountLine = this.cursor() as RetailPeriodicDiscountLine;
    ruleCopyLine.initFromPricingRule(GUPPricingRule::find(discountLine.LinePricingRule));

    element.pricingRuleCopyLine = ruleCopyLine;

    element.initInventTablePreview();

    return ret;
}

public void lookup()
{
    SysTableLookup          sysTableLookup = SysTableLookup::newParameters(tableNum(RetailPeriodicDiscount), this);

    Query                   query = new Query();
    QueryBuildDataSource    qbds  = query.addDataSource(tableNum(RetailPeriodicDiscount));
    qbds.addRange(fieldNum(RetailPeriodicDiscount, IsGUPDiscount)).value(SysQuery::value(NoYes::Yes));
    qbds.addRange(fieldNum(RetailPeriodicDiscount, Status)).value(SysQuery::value(RetailDisabledEnabled::Enabled));
    qbds.addRange(fieldNum(RetailPeriodicDiscount, PeriodicDiscountType)).value(SysQuery::value(RetailDiscountOfferTypeBase::DiscountOffer));

    QueryBuildDataSource qbdsJoin = qbds.addDataSource(tableNum(GUPPriceComponentCodeSetup));
    qbdsJoin.addLink(fieldNum(RetailPeriodicDiscount, PriceComponentCodeName), fieldNum(GUPPriceComponentCodeSetup, PriceComponentCodeName));
    qbdsJoin.addRange(fieldNum(GUPPriceComponentCodeSetup, CompoundCalculationBasis)).value(SysQuery::value(NoYes::No));

    sysTableLookup.addLookupfield(fieldNum(RetailPeriodicDiscount, OfferId));
    sysTableLookup.addLookupfield(fieldNum(RetailPeriodicDiscount, Name));
    sysTableLookup.addLookupfield(fieldNum(RetailPeriodicDiscount, PriceComponentCodeName));
    sysTableLookup.addLookupfield(fieldNum(RetailPeriodicDiscount, ValidFrom));
    sysTableLookup.addLookupfield(fieldNum(RetailPeriodicDiscount, ValidTo));
    sysTableLookup.parmQuery(query);

    sysTableLookup.performFormLookup();
}

public boolean modified()
{
    boolean ret = super();

    RetailPeriodicDiscount discount = RetailPeriodicDiscount::findByOfferId(this.valueStr());

    GUPPricingRuleCopy ruleCopyHeader;
    ruleCopyHeader.initFromPricingRule(GUPPricingRule::find(discount.HeaderPricingRule));

    element.pricingRuleCopyHeader = ruleCopyHeader;
    element.initCustTablePreview();

    offerIdRange.value(SysQuery::value(this.valueStr()));
    RetailPeriodicDiscountLine_ds.executeQuery();

    FromDate.dateValue(discount.ValidFrom);
    ToDate.dateValue(discount.ValidTo);

    return ret;
}
